(551226, 55876, 15768, '<td valign="top">//www.dpchallenge.com/image.php?IMAGE_ID=40319<br/>I hope you didn''t see this one before...</td>', '//www.dpchallenge.com/image.php?IMAGE_ID=40319I hope you didn''t see this one before...', '2004-01-21 00:42:55.000000', NULL, 1),
(551227, 55867, 6668, '<td valign="top">interesting observation for you to notice and capture that, nice shot.</td>', 'interesting observation for you to notice and capture that, nice shot.', '2004-01-21 00:43:00.000000', NULL, 1),
(551230, 56076, 6668, '<td valign="top">Although this is a very interesting shot...I''m not sure it fits in the road signs challenge, if I am missing something please pm me and correct me, maybe the answer is in the title which is in a language i cannot read.</td>', 'Although this is a very interesting shot...I''m not sure it fits in the road signs challenge, if I am missing something please pm me and correct me, maybe the answer is in the title which is in a language i cannot read.', '2004-01-21 00:45:30.000000', NULL, 1),
(551232, 56114, 6008, '<td valign="top">Technical - Great exposure! The disc of the sun is great just peeking out from the horizon and not overexposed either. The position of the clouds actually seem like they are traveling the direction of the sign too, and add a nice texture and color to the scene. The prairie gras also adds a nice texture and some height. The horizon line is unfortunately slightly tilted, and the perspective of the signs also seem to suggest a slanted angle also. It''s slightly crowded on the right, which makes it feel a little unbalanced but not overly so.<br/> <br/>Personal - It has a great atmosphere to it and wonderful tones.<br/> <br/>Overall - It''s a great capture, just needed a few tweaks to become a really wow shot.</td>', 'Technical - Great exposure! The disc of the sun is great just peeking out from the horizon and not overexposed either. The position of the clouds actually seem like they are traveling the direction of the sign too, and add a nice texture and color to the scene. The prairie gras also adds a nice texture and some height. The horizon line is unfortunately slightly tilted, and the perspective of the signs also seem to suggest a slanted angle also. It''s slightly crowded on the right, which makes it feel a little unbalanced but not overly so. Personal - It has a great atmosphere to it and wonderful tones. Overall - It''s a great capture, just needed a few tweaks to become a really wow shot.', '2004-01-21 00:46:19.000000', NULL, 1),
(551234, 56118, 6668, '<td valign="top">seems out of focus and a bit dark.</td>', 'seems out of focus and a bit dark.', '2004-01-21 00:46:51.000000', NULL, 1),
(551235, 55942, 15982, '<td valign="top">A little more of the sign would have been great, but still a nice picture</td>', 'A little more of the sign would have been great, but still a nice picture', '2004-01-21 00:47:17.000000', NULL, 1),
(551237, 56076, 6008, '<td valign="top">Not sure I see a connection here to road signs. I see a magnifying glass or lens with waterdrops over a picture of an eye. Outside of the challenge it''s an interesting shot.</td>', 'Not sure I see a connection here to road signs. I see a magnifying glass or lens with waterdrops over a picture of an eye. Outside of the challenge it''s an interesting shot.', '2004-01-21 00:48:40.000000', NULL, 1),
(551238, 55331, 327, '<td valign="top">Really old. Neat tones, looks great. I would like to see a few of the power lines removed but this is very good. I hope you do well in the challenge. Good luck.</td>', 'Really old. Neat tones, looks great. I would like to see a few of the power lines removed but this is very good. I hope you do well in the challenge. Good luck.', '2004-01-21 00:49:54.000000', NULL, 1),
(551239, 55603, 6008, '<td valign="top">Exposure is good - I like the simple sunset, the lit sign, and the silhouetted trees. The blue is nice and deep although there appears to be a small amount of noise, whether from the high ISO or the saturation of the blue in post-processing. The connection between sign and background is apt, and the uncluttered feeling is good too. Quite a mellow scene.</td>', 'Exposure is good - I like the simple sunset, the lit sign, and the silhouetted trees. The blue is nice and deep although there appears to be a small amount of noise, whether from the high ISO or the saturation of the blue in post-processing. The connection between sign and background is apt, and the uncluttered feeling is good too. Quite a mellow scene.', '2004-01-21 00:52:36.000000', NULL, 1),
(551242, 55861, 6668, '<td valign="top">to bad the sign was under all of those power lines, they steal the focus away from the school sign in my opinion.</td>', 'to bad the sign was under all of those power lines, they steal the focus away from the school sign in my opinion.', '2004-01-21 00:55:09.000000', NULL, 1),
(551243, 55922, 6668, '<td valign="top">Well then where is an appropriate place for the children to get loaded? LOL<br/> <br/>But seriously, I like the colors in this shot, I like the accents of the red doors and the red in the sign adds another element to the shot.</td>', 'Well then where is an appropriate place for the children to get loaded? LOL But seriously, I like the colors in this shot, I like the accents of the red doors and the red in the sign adds another element to the shot.', '2004-01-21 00:57:00.000000', NULL, 1),
(551249, 56051, 6388, '<td valign="top">hilarious.  one direction for each of my personalities.  i like the shot, even in the absence of the challenge (unlike many that are just snaps of signs).  Good eye, great title.</td>', 'hilarious.  one direction for each of my personalities.  i like the shot, even in the absence of the challenge (unlike many that are just snaps of signs).  Good eye, great title.', '2004-01-21 01:04:51.000000', NULL, 1),
(551250, 55533, 6668, '<td valign="top">Nice shot, I really like the bright vibrant colors, also an interesting subject. nice job. 10</td>', 'Nice shot, I really like the bright vibrant colors, also an interesting subject. nice job. 10', '2004-01-21 01:05:10.000000', NULL, 1),
