(551762, 55973, 13891, '<td valign="top">I like this shot but found the frame to be distracting.</td>', 'I like this shot but found the frame to be distracting.', '2004-01-21 09:28:40.000000', NULL, 1),
(551763, 55906, 16052, '<td valign="top">Nice sepia imagary.</td>', 'Nice sepia imagary.', '2004-01-21 09:29:22.000000', NULL, 1),
(551764, 55648, 15982, '<td valign="top">I like the picture. Good coalescence of road name and sky.</td>', 'I like the picture. Good coalescence of road name and sky.', '2004-01-21 09:29:49.000000', NULL, 1),
(551766, 55648, 13336, '<td valign="top">of the signs that "say what they mean," this one is the best.  Nice work on the saturation/desaturation. good composition with the angle and the negative space - it would have been nice if there wasn''t a bisecting sign, but you can''t help that and your choice of angle shows just enough of it so that it doesn''t intefere but doesn''t look like you tried to hide it either.</td>', 'of the signs that "say what they mean," this one is the best.  Nice work on the saturation/desaturation. good composition with the angle and the negative space - it would have been nice if there wasn''t a bisecting sign, but you can''t help that and your choice of angle shows just enough of it so that it doesn''t intefere but doesn''t look like you tried to hide it either.', '2004-01-21 09:30:10.000000', NULL, 1),
(551767, 55897, 16052, '<td valign="top">Dark and dull for me.  A more interesting (or slightly brighter) background would have helped.</td>', 'Dark and dull for me.  A more interesting (or slightly brighter) background would have helped.', '2004-01-21 09:31:14.000000', NULL, 1),
