(551770, 55891, 16052, '<td valign="top">Good color and composition.  Sign appears overexposed.</td>', 'Good color and composition.  Sign appears overexposed.', '2004-01-21 09:32:53.000000', NULL, 1),
(551771, 55861, 13336, '<td valign="top">yup, that''s just how i remember it!  interesting take on the subject - i really feel like i''ve been put in the school child''s shoes when i look at this.  there''s a lot of distracting lines in this shot, and the sign itself seems a little too much in shadow/undersaturated.  overall good effort but with room for improvement.</td>', 'yup, that''s just how i remember it!  interesting take on the subject - i really feel like i''ve been put in the school child''s shoes when i look at this.  there''s a lot of distracting lines in this shot, and the sign itself seems a little too much in shadow/undersaturated.  overall good effort but with room for improvement.', '2004-01-21 09:33:12.000000', NULL, 1),
(551772, 55923, 6668, '<td valign="top">The power lines distract from the sign to much, maybe a different sign or a different angle would have worked better.</td>', 'The power lines distract from the sign to much, maybe a different sign or a different angle would have worked better.', '2004-01-21 09:33:18.000000', NULL, 1),
