(551774, 55603, 13891, '<td valign="top">A great shot. Colours are a bit too saturated for my taste, but that is a personal (or posssibly geogphic) thing. Excellent composition.</td>', 'A great shot. Colours are a bit too saturated for my taste, but that is a personal (or posssibly geogphic) thing. Excellent composition.', '2004-01-21 09:34:14.000000', NULL, 1),
(551775, 56015, 16052, '<td valign="top">Nice.  I wish something other than trash bags were in the foreground with the sign, but i guess that couldn''t be helped.  Very well done.</td>', 'Nice.  I wish something other than trash bags were in the foreground with the sign, but i guess that couldn''t be helped.  Very well done.', '2004-01-21 09:34:20.000000', NULL, 1),
