(551792, 55919, 16052, '<td valign="top">Nice B&amp;W and composition.</td>', 'Nice B&W and composition.', '2004-01-21 09:41:25.000000', NULL, 1),
(551794, 55749, 13336, '<td valign="top">very nice tones here, a rich golden sepia, yet with a comanding blue still in the picture.  i agree that this works best with a close crop, but maybe you came in a little too close on this one where the iron gets cut off.  also, do we have to see the "parking" part of the sign?  it kind of sends a mixed message at first becaue i think about driving, then golf.  Perhaps the symbol alone with the clubs would work better?</td>', 'very nice tones here, a rich golden sepia, yet with a comanding blue still in the picture.  i agree that this works best with a close crop, but maybe you came in a little too close on this one where the iron gets cut off.  also, do we have to see the "parking" part of the sign?  it kind of sends a mixed message at first becaue i think about driving, then golf.  Perhaps the symbol alone with the clubs would work better?', '2004-01-21 09:42:39.000000', NULL, 1),
(551795, 56030, 6100, '<td valign="top">This one works best because of your title! Exposure and color are good. Somehow, I wish the background were darker so it didn''t command so much attention. 7</td>', 'This one works best because of your title! Exposure and color are good. Somehow, I wish the background were darker so it didn''t command so much attention. 7', '2004-01-21 09:43:11.000000', NULL, 1),
