(552635, 55394, 259, '<td valign="top">nice job, i think the abstract shots in this challenge are more interesting.</td>', 'nice job, i think the abstract shots in this challenge are more interesting.', '2004-01-21 17:10:15.000000', NULL, 1),
(552637, 55704, 259, '<td valign="top">nicely exposed in such tough conditions</td>', 'nicely exposed in such tough conditions', '2004-01-21 17:12:11.000000', NULL, 1),
