(554984, 55354, 6597, '<td valign="top">Good placement of road sign good background  road sign as main focus is good 7</td>', 'Good placement of road sign good background  road sign as main focus is good 7', '2004-01-23 21:15:34.000000', NULL, 1),
(554989, 56002, 10170, '<td valign="top">Oh, very well spotted!</td>', 'Oh, very well spotted!', '2004-01-23 21:41:20.000000', NULL, 1),
(554994, 55754, 2792, '<td valign="top">Beautiful shot, but you can barely notice the sign...</td>', 'Beautiful shot, but you can barely notice the sign...', '2004-01-23 21:44:58.000000', NULL, 1),
(554995, 55625, 13305, '<td valign="top">interesting, but I think a straightforward image would be more effective.</td>', 'interesting, but I think a straightforward image would be more effective.', '2004-01-23 21:45:25.000000', NULL, 1),
(554996, 55999, 2792, '<td valign="top">Funny!  Don''t like the angle the sign is leaning at though.</td>', 'Funny!  Don''t like the angle the sign is leaning at though.', '2004-01-23 21:47:24.000000', NULL, 1),
(554997, 55852, 13305, '<td valign="top">Feels too contrived.  Try a bottle at the bottom of the stop sign beside the road.</td>', 'Feels too contrived.  Try a bottle at the bottom of the stop sign beside the road.', '2004-01-23 21:47:33.000000', NULL, 1),
(554998, 55736, 13305, '<td valign="top">Good image.  It''s not bad, but I would prefer the background to be in sharp focus also.  Just my slant on it.</td>', 'Good image.  It''s not bad, but I would prefer the background to be in sharp focus also.  Just my slant on it.', '2004-01-23 21:51:23.000000', NULL, 1),
(555000, 56050, 14700, '<td valign="top">Nice get, but I think your white balance is off.  6 could have been 7.</td>', 'Nice get, but I think your white balance is off.  6 could have been 7.', '2004-01-23 21:54:11.000000', NULL, 1),
(555003, 55986, 14700, '<td valign="top">White balance is off. 5 could have been 6.</td>', 'White balance is off. 5 could have been 6.', '2004-01-23 21:56:01.000000', NULL, 1),
(555005, 56052, 14700, '<td valign="top">Clever.</td>', 'Clever.', '2004-01-23 21:56:33.000000', NULL, 1),
(555023, 55826, 4767, '<td valign="top">Great eye!  good control - the snow has DETAIL in it!  You GO!</td>', 'Great eye!  good control - the snow has DETAIL in it!  You GO!', '2004-01-23 22:47:48.000000', NULL, 1),
(555025, 56076, 4767, '<td valign="top">I am not familiar with this road sign.  Interesting photo, but doesn''t look on topic to me/</td>', 'I am not familiar with this road sign.  Interesting photo, but doesn''t look on topic to me/', '2004-01-23 22:50:56.000000', NULL, 1),
(555026, 55749, 4767, '<td valign="top">Interesting design, excellent color but it seems a little bizarre for this challenge...</td>', 'Interesting design, excellent color but it seems a little bizarre for this challenge...', '2004-01-23 22:52:45.000000', NULL, 1),
(555051, 55530, 10686, '<td valign="top">I love the curvy lines and the bold red and blue</td>', 'I love the curvy lines and the bold red and blue', '2004-01-24 00:07:47.000000', NULL, 1),
(555060, 56077, 10686, '<td valign="top">Great colors and composition, maybe more of the orange would be nice, but still, very nice</td>', 'Great colors and composition, maybe more of the orange would be nice, but still, very nice', '2004-01-24 00:25:46.000000', NULL, 1),
(555064, 56076, 10686, '<td valign="top">interesting shot, but how does it fit with road signs?<br/></td>', 'interesting shot, but how does it fit with road signs?', '2004-01-24 00:31:27.000000', NULL, 1),
(555066, 56060, 10686, '<td valign="top">Honey, Ware are we going?</td>', 'Honey, Ware are we going?', '2004-01-24 00:32:06.000000', NULL, 1),
(555068, 55983, 10686, '<td valign="top">seems a bit overexposed</td>', 'seems a bit overexposed', '2004-01-24 00:33:01.000000', NULL, 1),
(555069, 56057, 10686, '<td valign="top">looks like a license plate</td>', 'looks like a license plate', '2004-01-24 00:34:42.000000', NULL, 1),
(555079, 55603, 16335, '<td valign="top">Very nice! too bad the sun wasn''t a just little higher on the horizon.</td>', 'Very nice! too bad the sun wasn''t a just little higher on the horizon.', '2004-01-24 00:48:18.000000', NULL, 1),
(555080, 55530, 16335, '<td valign="top">Nice angle on this shot.</td>', 'Nice angle on this shot.', '2004-01-24 00:50:53.000000', NULL, 1),
(555082, 55836, 16335, '<td valign="top">Not bad, but a little blurred on the back sign.</td>', 'Not bad, but a little blurred on the back sign.', '2004-01-24 00:55:27.000000', NULL, 1),
(555083, 55826, 16335, '<td valign="top">Just a little out of place, wouldn''t you say? Would the flamingo''s be blue instead of pink in that area?</td>', 'Just a little out of place, wouldn''t you say? Would the flamingo''s be blue instead of pink in that area?', '2004-01-24 00:57:00.000000', NULL, 1),
(555084, 56085, 16335, '<td valign="top">Nice crisp and clear shot! Well done.</td>', 'Nice crisp and clear shot! Well done.', '2004-01-24 00:58:23.000000', NULL, 1),
(555087, 55407, 8054, '<td valign="top">Nice work with good composure. The colors seem a bit unreal to me, though.</td>', 'Nice work with good composure. The colors seem a bit unreal to me, though.', '2004-01-24 01:00:33.000000', NULL, 1),
(555090, 56076, 8054, '<td valign="top">I don''t see the connection between this and a road sign not to mention that I have no idea what the title means. The water drops are sort-of interesting.</td>', 'I don''t see the connection between this and a road sign not to mention that I have no idea what the title means. The water drops are sort-of interesting.', '2004-01-24 01:02:15.000000', NULL, 1),
(555091, 55518, 16335, '<td valign="top">Does the speed limit include boats? Too bad you couldn''t have found a sign here that said "No parking at any time"!</td>', 'Does the speed limit include boats? Too bad you couldn''t have found a sign here that said "No parking at any time"!', '2004-01-24 01:02:34.000000', NULL, 1),
(555092, 55648, 8054, '<td valign="top">Great use of negative space. Nice contrast between the gray sky and the street sign. By chance, was the cross street Boring Road?  :)</td>', 'Great use of negative space. Nice contrast between the gray sky and the street sign. By chance, was the cross street Boring Road?  :)', '2004-01-24 01:03:29.000000', NULL, 1),
(555093, 56105, 16335, '<td valign="top">Nice shot! sign is a little dark, but still a good picture!</td>', 'Nice shot! sign is a little dark, but still a good picture!', '2004-01-24 01:03:44.000000', NULL, 1),
(555096, 56121, 8054, '<td valign="top">Normally I don''t like the way the flash lights up the sign but it has an interesting effect here. It''s as if the sign is illuminated. The trees in the background would have looked better with more creative use of DOF. Good effort, however.</td>', 'Normally I don''t like the way the flash lights up the sign but it has an interesting effect here. It''s as if the sign is illuminated. The trees in the background would have looked better with more creative use of DOF. Good effort, however.', '2004-01-24 01:05:39.000000', NULL, 1),
(555097, 56005, 16335, '<td valign="top">I wish I could ski that good!</td>', 'I wish I could ski that good!', '2004-01-24 01:06:21.000000', NULL, 1),
(555098, 56069, 8054, '<td valign="top">Too phalic and not quite a street sign. Interesting duotone, though.</td>', 'Too phalic and not quite a street sign. Interesting duotone, though.', '2004-01-24 01:06:31.000000', NULL, 1),
(555099, 55754, 16335, '<td valign="top">Nice shot of the sky, but what happened to the sign?</td>', 'Nice shot of the sky, but what happened to the sign?', '2004-01-24 01:07:07.000000', NULL, 1),
(555101, 56121, 16335, '<td valign="top">I don''t think I have seen a teetor-totter sign before.</td>', 'I don''t think I have seen a teetor-totter sign before.', '2004-01-24 01:08:36.000000', NULL, 1),
(555102, 55905, 8054, '<td valign="top">Background is a bit overexposed and the sign is not illuminated enough. This is due to a tough lighting situation. I probably would have waited for a more opportune moment. Also, this is a classic case for use of shallow DOF as I tend to look at the background with equal effort as the sign.</td>', 'Background is a bit overexposed and the sign is not illuminated enough. This is due to a tough lighting situation. I probably would have waited for a more opportune moment. Also, this is a classic case for use of shallow DOF as I tend to look at the background with equal effort as the sign.', '2004-01-24 01:08:42.000000', NULL, 1),
(555104, 55894, 16335, '<td valign="top">Funny! I hope the sign talks too! or is that for the seeing eye dog to read?</td>', 'Funny! I hope the sign talks too! or is that for the seeing eye dog to read?', '2004-01-24 01:11:13.000000', NULL, 1),
(555105, 55852, 16335, '<td valign="top">Good message, might be a little better if more of the stop sign was in the field of view. Nice sharp image though!</td>', 'Good message, might be a little better if more of the stop sign was in the field of view. Nice sharp image though!', '2004-01-24 01:14:02.000000', NULL, 1),
(555106, 56055, 16335, '<td valign="top">Nice clear shot, good definition, good color.</td>', 'Nice clear shot, good definition, good color.', '2004-01-24 01:15:37.000000', NULL, 1),
(555107, 55613, 16335, '<td valign="top">Busy sign, nice to see how you got all of the signs in the frame, despite the different directions.</td>', 'Busy sign, nice to see how you got all of the signs in the frame, despite the different directions.', '2004-01-24 01:22:53.000000', NULL, 1),
(555108, 55473, 16335, '<td valign="top">Not a bad shot, but I don''t understand what it has to do with the challenge?</td>', 'Not a bad shot, but I don''t understand what it has to do with the challenge?', '2004-01-24 01:27:46.000000', NULL, 1),
(555109, 55543, 16335, '<td valign="top">Do you get a tax receipt too?</td>', 'Do you get a tax receipt too?', '2004-01-24 01:29:24.000000', NULL, 1),
(555122, 56081, 6804, '<td valign="top">This is just perfect! The coloring of the leaves matched to the sign is what makes this all fit together for me. Beautiful work!!! This is my favorite of the challenge.</td>', 'This is just perfect! The coloring of the leaves matched to the sign is what makes this all fit together for me. Beautiful work!!! This is my favorite of the challenge.', '2004-01-24 02:48:05.000000', NULL, 1),
(555123, 55331, 6804, '<td valign="top">This is one of my favorite of the challenge. The worn out R/R sign and the worn down building all fit together nicely here. I actually even like the wires in this shot, they give this a feel of having been left behind to wither away.  Great color tone and detail. 8</td>', 'This is one of my favorite of the challenge. The worn out R/R sign and the worn down building all fit together nicely here. I actually even like the wires in this shot, they give this a feel of having been left behind to wither away.  Great color tone and detail. 8', '2004-01-24 02:53:35.000000', NULL, 1),
(555124, 55207, 6804, '<td valign="top">I love the color selection on this! The few leaves matching up with the sign is a nice touch. Great detail in the swamp. Nice angle on the sign, it leads the eyes into the picture. This is one of my top 5.</td>', 'I love the color selection on this! The few leaves matching up with the sign is a nice touch. Great detail in the swamp. Nice angle on the sign, it leads the eyes into the picture. This is one of my top 5.', '2004-01-24 02:57:25.000000', NULL, 1),
(555126, 55913, 6804, '<td valign="top">This is a refreshing take on the signs. Nice composition. This is in my top 5 for this challenge. Great placement of the sign and the tree. Good color selection B/W, and good crop.</td>', 'This is a refreshing take on the signs. Nice composition. This is in my top 5 for this challenge. Great placement of the sign and the tree. Good color selection B/W, and good crop.', '2004-01-24 03:06:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(555153, 55958, 15703, '<td valign="top">Mmmm. Different. A very high mark has just been awarded. 10.</td>', 'Mmmm. Different. A very high mark has just been awarded. 10.', '2004-01-24 08:00:03.000000', NULL, 1),
(555155, 55514, 15703, '<td valign="top">A rather boring sign with an unexciting background. So I give you a 6 for doing so well with poor material.</td>', 'A rather boring sign with an unexciting background. So I give you a 6 for doing so well with poor material.', '2004-01-24 08:02:16.000000', NULL, 1),
(555160, 55913, 15703, '<td valign="top">Very nice. Original, clever, well done, well exposed, nicely "framed" (tee-hee!). A 9 for you, I think.</td>', 'Very nice. Original, clever, well done, well exposed, nicely "framed" (tee-hee!). A 9 for you, I think.', '2004-01-24 08:06:02.000000', NULL, 1),
(555162, 56098, 15703, '<td valign="top">A very nice, interesting shot. Pleasing colours. An 8, I think.</td>', 'A very nice, interesting shot. Pleasing colours. An 8, I think.', '2004-01-24 08:15:55.000000', NULL, 1),
(555163, 56042, 15703, '<td valign="top">Punchy colours. Very different.</td>', 'Punchy colours. Very different.', '2004-01-24 08:17:45.000000', NULL, 1),
(555165, 55229, 15703, '<td valign="top">Another nicely different approach. The pleasing colours lift this into being a very interesting shot.</td>', 'Another nicely different approach. The pleasing colours lift this into being a very interesting shot.', '2004-01-24 08:21:06.000000', NULL, 1),
(555166, 55867, 15703, '<td valign="top">What a thoughtful little picture. Very well executed.</td>', 'What a thoughtful little picture. Very well executed.', '2004-01-24 08:24:35.000000', NULL, 1),
(555167, 56135, 9977, '<td valign="top">Superb Pictures, great levels and contrast ... !</td>', 'Superb Pictures, great levels and contrast ... !', '2004-01-24 08:25:26.000000', NULL, 1),
(555168, 55433, 9977, '<td valign="top">Great Composition ...</td>', 'Great Composition ...', '2004-01-24 08:25:58.000000', NULL, 1),
(555169, 55530, 9977, '<td valign="top">Great Colors</td>', 'Great Colors', '2004-01-24 08:26:50.000000', NULL, 1),
(555170, 55890, 15703, '<td valign="top">Witty. And a very nice photo, too.</td>', 'Witty. And a very nice photo, too.', '2004-01-24 08:26:53.000000', NULL, 1),
(555171, 55742, 9977, '<td valign="top">Great composition ... who was driving ???</td>', 'Great composition ... who was driving ???', '2004-01-24 08:27:36.000000', NULL, 1),
(555172, 55865, 9977, '<td valign="top">Great composition</td>', 'Great composition', '2004-01-24 08:28:06.000000', NULL, 1),
(555173, 56041, 9977, '<td valign="top">I never seen this one, where is this sign ???</td>', 'I never seen this one, where is this sign ???', '2004-01-24 08:28:52.000000', NULL, 1),
(555175, 55533, 9977, '<td valign="top">????</td>', '????', '2004-01-24 08:29:36.000000', NULL, 1),
(555176, 56077, 15703, '<td valign="top">Nicely framed. Good colours. Well done.</td>', 'Nicely framed. Good colours. Well done.', '2004-01-24 08:30:23.000000', NULL, 1),
(555184, 56015, 15242, '<td valign="top">would it have been better without the garbage bags there?</td>', 'would it have been better without the garbage bags there?', '2004-01-24 08:45:04.000000', NULL, 1),
(555185, 55623, 15242, '<td valign="top">Crop of on the left to get rid of that annoying white spot on top and I like it better.</td>', 'Crop of on the left to get rid of that annoying white spot on top and I like it better.', '2004-01-24 08:47:27.000000', NULL, 1),
(555186, 56071, 15242, '<td valign="top">I really like the scene and the colors, but I''d be curious to see this in black and white.  Great shot.</td>', 'I really like the scene and the colors, but I''d be curious to see this in black and white.  Great shot.', '2004-01-24 08:50:13.000000', NULL, 1),
(555188, 56041, 15242, '<td valign="top">If you loweres your angle a little more to get the sign to block more of the sun this may have come out better.</td>', 'If you loweres your angle a little more to get the sign to block more of the sun this may have come out better.', '2004-01-24 08:51:18.000000', NULL, 1),
(555190, 56031, 15242, '<td valign="top">B&amp;W would mask the drab sky and add emotion.  Good eye.</td>', 'B&W would mask the drab sky and add emotion.  Good eye.', '2004-01-24 08:52:36.000000', NULL, 1),
(555191, 56108, 15242, '<td valign="top">cell phone cam or were you going for the fuzzy poor quality look?</td>', 'cell phone cam or were you going for the fuzzy poor quality look?', '2004-01-24 08:54:31.000000', NULL, 1),
(555192, 55963, 15242, '<td valign="top">Nice shot, you could take a lot of great pictures here.  Could you have gotton rid of that glare spot by moving a little to your right?  or you could have moved to your left and let the sign cover the glare spot.</td>', 'Nice shot, you could take a lot of great pictures here.  Could you have gotton rid of that glare spot by moving a little to your right?  or you could have moved to your left and let the sign cover the glare spot.', '2004-01-24 08:57:19.000000', NULL, 1),
(555193, 56069, 15242, '<td valign="top">Would have done very well in the phalic symbol challenge but I don''t see a road sign.  I don''t even see a sign.</td>', 'Would have done very well in the phalic symbol challenge but I don''t see a road sign.  I don''t even see a sign.', '2004-01-24 08:58:50.000000', NULL, 1),
(555194, 55670, 15242, '<td valign="top">Great shot, should win a ribbon.</td>', 'Great shot, should win a ribbon.', '2004-01-24 09:00:17.000000', NULL, 1),
(555195, 55648, 15242, '<td valign="top">Great shot, but there seems to be a weird effect on the sky.  Maybe too much post processing?</td>', 'Great shot, but there seems to be a weird effect on the sky.  Maybe too much post processing?', '2004-01-24 09:01:25.000000', NULL, 1),
(555196, 55731, 15242, '<td valign="top">Might do better rotated 180 degrees.</td>', 'Might do better rotated 180 degrees.', '2004-01-24 09:02:22.000000', NULL, 1),
(555197, 56132, 15242, '<td valign="top">Focus seems very soft.  It works for the leaves, but it doesn''t work on the sign and post.</td>', 'Focus seems very soft.  It works for the leaves, but it doesn''t work on the sign and post.', '2004-01-24 09:03:57.000000', NULL, 1),
(555198, 56118, 15242, '<td valign="top">I don''t like the angle or the subject.  Not at all interesting.</td>', 'I don''t like the angle or the subject.  Not at all interesting.', '2004-01-24 09:05:34.000000', NULL, 1),
(555199, 55870, 15242, '<td valign="top">Flowers add a nice touch.  Crop out the garbage can!</td>', 'Flowers add a nice touch.  Crop out the garbage can!', '2004-01-24 09:06:32.000000', NULL, 1),
(555201, 55625, 15242, '<td valign="top">I do like the way the signs pop out at you, but the over proccesed shot thing really doesn''t work for me.  It may be better just cropping around the stop sign?  The mall sign makes me feel like I''m looking at an advertisement.</td>', 'I do like the way the signs pop out at you, but the over proccesed shot thing really doesn''t work for me.  It may be better just cropping around the stop sign?  The mall sign makes me feel like I''m looking at an advertisement.', '2004-01-24 09:10:18.000000', NULL, 1),
(555202, 55921, 6008, '<td valign="top">A slight step to your left and a step back so that the cross was full in the frame and could be read a tad more easier would have improved this a little more, I think. It''s an interesting shot, certainly makes one think while viewing it. The black and white was a good choice to make it seem somewhat harsher. An unfortunate photo opportunity, but a good message to send.</td>', 'A slight step to your left and a step back so that the cross was full in the frame and could be read a tad more easier would have improved this a little more, I think. It''s an interesting shot, certainly makes one think while viewing it. The black and white was a good choice to make it seem somewhat harsher. An unfortunate photo opportunity, but a good message to send.', '2004-01-24 09:10:21.000000', NULL, 1),
(555205, 56144, 15242, '<td valign="top">Great scene!  Maybe try B&amp;W?</td>', 'Great scene!  Maybe try B&W?', '2004-01-24 09:11:39.000000', NULL, 1),
(555206, 55959, 15242, '<td valign="top">Thanks for the translation.  I really like this shot.</td>', 'Thanks for the translation.  I really like this shot.', '2004-01-24 09:12:33.000000', NULL, 1),
(555207, 55542, 6008, '<td valign="top">It''s the back of the sign so I''m assuming it isnt an actual no shooting area sign and the title is just there for the humor. That said it''s an interesting shot. The background of the blue skies and the mountains is great, and I like the foreground of the road, although it''s a tad dark. That one star-shaped light coming through the hole also adds interest. Unfortunately the perspective of the sign makes it look tilted, which is slightly offputting. Overall it''s a good shot.</td>', 'It''s the back of the sign so I''m assuming it isnt an actual no shooting area sign and the title is just there for the humor. That said it''s an interesting shot. The background of the blue skies and the mountains is great, and I like the foreground of the road, although it''s a tad dark. That one star-shaped light coming through the hole also adds interest. Unfortunately the perspective of the sign makes it look tilted, which is slightly offputting. Overall it''s a good shot.', '2004-01-24 09:14:00.000000', NULL, 1),
(555208, 56072, 15242, '<td valign="top">Not sure if it was intentional, but way over adjusted. The lettering and straight edges shouldn''t be stair stepped.</td>', 'Not sure if it was intentional, but way over adjusted. The lettering and straight edges shouldn''t be stair stepped.', '2004-01-24 09:14:16.000000', NULL, 1),
(555209, 56124, 6008, '<td valign="top">The sign is very clear, vibrant, and straight! The dof is excellent to isolate the sign, yet have some context in the background without being too distracting. The second sign compliments the first well and it gives a great depth to the image.</td>', 'The sign is very clear, vibrant, and straight! The dof is excellent to isolate the sign, yet have some context in the background without being too distracting. The second sign compliments the first well and it gives a great depth to the image.', '2004-01-24 09:15:57.000000', NULL, 1),
(555210, 55704, 15242, '<td valign="top">Nice shot, next time use the sign pole to block out that glare spot.</td>', 'Nice shot, next time use the sign pole to block out that glare spot.', '2004-01-24 09:16:13.000000', NULL, 1),
(555211, 55324, 15242, '<td valign="top">A little closer to the sign might have been better so it would be more clear.</td>', 'A little closer to the sign might have been better so it would be more clear.', '2004-01-24 09:17:10.000000', NULL, 1),
(555212, 55936, 15242, '<td valign="top">Sorry, I don''t find this the least bit appealing.</td>', 'Sorry, I don''t find this the least bit appealing.', '2004-01-24 09:18:52.000000', NULL, 1),
(555213, 56063, 6008, '<td valign="top">The quality of this shot is not the best. It''s slightly blurry, and I wonder if this was taken in a speeding car. The sign has humor value, but the background is too distracting and ''close'' to the sign. Compositionally it''s fine.</td>', 'The quality of this shot is not the best. It''s slightly blurry, and I wonder if this was taken in a speeding car. The sign has humor value, but the background is too distracting and ''close'' to the sign. Compositionally it''s fine.', '2004-01-24 09:19:37.000000', NULL, 1),
(555227, 55393, 15855, '<td valign="top">That''s a good one!</td>', 'That''s a good one!', '2004-01-24 09:51:56.000000', NULL, 1),
(555236, 55836, 15855, '<td valign="top">This one made me laugh!</td>', 'This one made me laugh!', '2004-01-24 10:08:40.000000', NULL, 1),
(555239, 55419, 15855, '<td valign="top">yes....pretty scary! beautiful shot!</td>', 'yes....pretty scary! beautiful shot!', '2004-01-24 10:12:05.000000', NULL, 1),
(555267, 55890, 11897, '<td valign="top">I get the idea, nice photograph.</td>', 'I get the idea, nice photograph.', '2004-01-24 11:02:55.000000', NULL, 1),
(555270, 55331, 11897, '<td valign="top">I like the picture and the effect, if I were to criticise at all it would be that the sign just doesn''t stand out enough. Maybe a different angle would have helped.<br/>Still a good one should do well,<br/>Paul.</td>', 'I like the picture and the effect, if I were to criticise at all it would be that the sign just doesn''t stand out enough. Maybe a different angle would have helped.Still a good one should do well,Paul.', '2004-01-24 11:09:00.000000', NULL, 1),
(555271, 56052, 11897, '<td valign="top">I don''t. its been a long time, great idea.</td>', 'I don''t. its been a long time, great idea.', '2004-01-24 11:09:48.000000', NULL, 1),
(555272, 55876, 11897, '<td valign="top">Well found, good one.</td>', 'Well found, good one.', '2004-01-24 11:10:18.000000', NULL, 1),
(555273, 56058, 11897, '<td valign="top">Excellent</td>', 'Excellent', '2004-01-24 11:10:56.000000', NULL, 1),
(555274, 55512, 11897, '<td valign="top">Great shot, may have improved it with forced flash.</td>', 'Great shot, may have improved it with forced flash.', '2004-01-24 11:13:30.000000', NULL, 1),
