(555995, 56120, 15654, '<td valign="top">I thinkl the point of view of this photo is really witty, it seems at first sight that the car at the bottom has crashed at the bottom of the road. Cool.</td>', 'I thinkl the point of view of this photo is really witty, it seems at first sight that the car at the bottom has crashed at the bottom of the road. Cool.', '2004-01-25 06:32:17.000000', NULL, 1),
(555996, 55407, 15654, '<td valign="top">Very dramatic outset, cool.</td>', 'Very dramatic outset, cool.', '2004-01-25 06:33:30.000000', NULL, 1),
(556000, 56159, 15654, '<td valign="top">I really like this photo. It''s full of metaphors and if one is very imaginative one can draw analogies with the political events happening in the world nowadays. It would be great if there was a picture of another sign like that taken in Teeran and saying west on top of it. It is a pity you could not see the transcendence of your work and named it with an unfortunate name like that, still you get a high vote for the work.</td>', 'I really like this photo. It''s full of metaphors and if one is very imaginative one can draw analogies with the political events happening in the world nowadays. It would be great if there was a picture of another sign like that taken in Teeran and saying west on top of it. It is a pity you could not see the transcendence of your work and named it with an unfortunate name like that, still you get a high vote for the work.', '2004-01-25 06:42:42.000000', NULL, 1),
(556002, 56080, 15654, '<td valign="top">That is a good name for the work. Some people simply destroy the possibility of getting a good vote by entering really silly names or descriptions that are too obvious. Great work, my highest vote: 10!</td>', 'That is a good name for the work. Some people simply destroy the possibility of getting a good vote by entering really silly names or descriptions that are too obvious. Great work, my highest vote: 10!', '2004-01-25 06:47:03.000000', NULL, 1),
(556003, 56031, 15654, '<td valign="top">Great composition.</td>', 'Great composition.', '2004-01-25 06:49:10.000000', NULL, 1),
(556004, 55923, 15654, '<td valign="top">This picture is so cool!!! Blody hell, it is the best composition I have seen so far, well done! My best vote for you too:10!!!</td>', 'This picture is so cool!!! Blody hell, it is the best composition I have seen so far, well done! My best vote for you too:10!!!', '2004-01-25 06:51:30.000000', NULL, 1),
(556005, 55530, 15654, '<td valign="top">That is cool man!</td>', 'That is cool man!', '2004-01-25 06:53:02.000000', NULL, 1),
(556006, 56155, 15654, '<td valign="top">He he he, is it my South American mind or is this photo full of sexual insinuations, please folks don''t take my opinion to judge the pic. I really like it although the blurred background did not help in setting up an environment.</td>', 'He he he, is it my South American mind or is this photo full of sexual insinuations, please folks don''t take my opinion to judge the pic. I really like it although the blurred background did not help in setting up an environment.', '2004-01-25 06:55:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(556007, 56043, 15654, '<td valign="top">He he he he. Cool, we are going to use this photo as evidence.</td>', 'He he he he. Cool, we are going to use this photo as evidence.', '2004-01-25 06:56:02.000000', NULL, 1),
(556008, 56077, 15654, '<td valign="top">Greta composition, minimalistic yet ironic and funny.</td>', 'Greta composition, minimalistic yet ironic and funny.', '2004-01-25 06:56:47.000000', NULL, 1),
(556009, 55861, 15654, '<td valign="top">Great perspective, obvious name though. You get my highest vote: 10!</td>', 'Great perspective, obvious name though. You get my highest vote: 10!', '2004-01-25 06:58:36.000000', NULL, 1),
(556010, 56076, 15199, '<td valign="top">While its a truly good shot, I do not see the relevance to road signs and the non-english title makes it the more confusing.</td>', 'While its a truly good shot, I do not see the relevance to road signs and the non-english title makes it the more confusing.', '2004-01-25 06:59:09.000000', NULL, 1),
(556011, 56124, 15199, '<td valign="top">Awesome DOF!!</td>', 'Awesome DOF!!', '2004-01-25 07:00:23.000000', NULL, 1),
(556039, 55407, 3540, '<td valign="top">This doesn''t do much for me in any real creative ways, but technically everything is pretty sound and the colors are gorgeous. 7</td>', 'This doesn''t do much for me in any real creative ways, but technically everything is pretty sound and the colors are gorgeous. 7', '2004-01-25 08:29:28.000000', NULL, 1),
(556042, 55736, 3540, '<td valign="top">Very lifeless shot.  It should be to a point.  but I think maybe if it were a little less exposed it would make it a little creepier.   Good find and capture.</td>', 'Very lifeless shot.  It should be to a point.  but I think maybe if it were a little less exposed it would make it a little creepier.   Good find and capture.', '2004-01-25 08:31:44.000000', NULL, 1),
(556043, 55236, 3540, '<td valign="top">Very creative.  I really like this.   Maybe it isn''t the hardest photograph or the prettiest one, but I like it, especially for this rotten challenge. 8</td>', 'Very creative.  I really like this.   Maybe it isn''t the hardest photograph or the prettiest one, but I like it, especially for this rotten challenge. 8', '2004-01-25 08:33:55.000000', NULL, 1),
(556046, 55733, 3540, '<td valign="top">I didn''t realize they liked to shop to the point they meritted their own sign to cross the streets.   I enjoy this shot, although photographically I don''t see much that I like.  It can be funny still without being Ansel Adams-ish. Good Luck</td>', 'I didn''t realize they liked to shop to the point they meritted their own sign to cross the streets.   I enjoy this shot, although photographically I don''t see much that I like.  It can be funny still without being Ansel Adams-ish. Good Luck', '2004-01-25 08:37:05.000000', NULL, 1),
(556051, 55854, 3540, '<td valign="top">Nice warm colors.  Too bad that sign is in the way it''d be a ...... oh wait, that''s what this is all about.  All kidding aside, its a nice warm picture.  Looks like the sun is coming up and its gonna be a great day.  Good luck</td>', 'Nice warm colors.  Too bad that sign is in the way it''d be a ...... oh wait, that''s what this is all about.  All kidding aside, its a nice warm picture.  Looks like the sun is coming up and its gonna be a great day.  Good luck', '2004-01-25 08:45:05.000000', NULL, 1),
(556056, 55552, 3540, '<td valign="top">I wouldn''t generally call this much of a road sign.  The whole picture is a little dull.  maybe boosting the contrast would''ve added a little more life.</td>', 'I wouldn''t generally call this much of a road sign.  The whole picture is a little dull.  maybe boosting the contrast would''ve added a little more life.', '2004-01-25 08:54:13.000000', NULL, 1),
(556065, 55670, 3540, '<td valign="top">Very creepy surreal shot.  The sign looks like its stuck on after the fact.  The cityscape is just a little too small.  I like how the sky is opening up in the right side of the frame.  Too bad it couldn''t have done that a little more.  I reallly like the way htis was taken.  Good work.</td>', 'Very creepy surreal shot.  The sign looks like its stuck on after the fact.  The cityscape is just a little too small.  I like how the sky is opening up in the right side of the frame.  Too bad it couldn''t have done that a little more.  I reallly like the way htis was taken.  Good work.', '2004-01-25 09:02:02.000000', NULL, 1),
(556075, 55346, 3540, '<td valign="top">This is a great sign.  The picture isn''t really that great.  But I think the sign is very clever.  good find</td>', 'This is a great sign.  The picture isn''t really that great.  But I think the sign is very clever.  good find', '2004-01-25 09:14:36.000000', NULL, 1),
(556080, 55419, 3540, '<td valign="top">wow, 2 green lights, now that might be a problem.  I''m not real sure that''s a road sign, but hey, close enough for me.  On second thought, you do have a roadsign in there.</td>', 'wow, 2 green lights, now that might be a problem.  I''m not real sure that''s a road sign, but hey, close enough for me.  On second thought, you do have a roadsign in there.', '2004-01-25 09:17:10.000000', NULL, 1),
(556081, 55511, 3540, '<td valign="top">It''s strange how the government deems that certain children are learning disabled and that they don''t know better than to go play in the road.  I wonder who makes those decisions.</td>', 'It''s strange how the government deems that certain children are learning disabled and that they don''t know better than to go play in the road.  I wonder who makes those decisions.', '2004-01-25 09:18:40.000000', NULL, 1),
(556084, 55835, 3540, '<td valign="top">Now that''s ironic.  Good find.  Too bad the sign couldn''t have been in focus instead of the fence.  The wonderful world of autofocus....</td>', 'Now that''s ironic.  Good find.  Too bad the sign couldn''t have been in focus instead of the fence.  The wonderful world of autofocus....', '2004-01-25 09:19:42.000000', NULL, 1),
(556088, 55207, 3540, '<td valign="top">I don''t really qualify this as a road sign.  I''m sure people driving by are not real intent on feeding the alligators on the go.  Its a good sign and all, just not the best example of ROAD sign to me.</td>', 'I don''t really qualify this as a road sign.  I''m sure people driving by are not real intent on feeding the alligators on the go.  Its a good sign and all, just not the best example of ROAD sign to me.', '2004-01-25 09:22:38.000000', NULL, 1),
(556092, 55543, 3540, '<td valign="top">well if you did I hope you got a tax credit for it.  This is a strange combination of signs.  Good find.</td>', 'well if you did I hope you got a tax credit for it.  This is a strange combination of signs.  Good find.', '2004-01-25 09:24:01.000000', NULL, 1),
(556094, 55876, 3540, '<td valign="top">Very ironic.  White stones are blown out and it seems that the rest of the photo could use more contrast.  A tough situation to be in.  Part of the phoot needs more contrast, the other part needs less exposure.  Good find on the sign though.</td>', 'Very ironic.  White stones are blown out and it seems that the rest of the photo could use more contrast.  A tough situation to be in.  Part of the phoot needs more contrast, the other part needs less exposure.  Good find on the sign though.', '2004-01-25 09:26:03.000000', NULL, 1),
(556096, 55546, 3540, '<td valign="top">Looks like you should have taken this photo about 20 minutes later so the sun wasn''t so hot.  Good colors and all, just the sun is really super bright.</td>', 'Looks like you should have taken this photo about 20 minutes later so the sun wasn''t so hot.  Good colors and all, just the sun is really super bright.', '2004-01-25 09:27:37.000000', NULL, 1),
(556099, 55533, 3540, '<td valign="top">This is really funny. Nice job to capture this one.  Good colors and a nice clear photo with an obvious theme to it.  Good work and good luck 8</td>', 'This is really funny. Nice job to capture this one.  Good colors and a nice clear photo with an obvious theme to it.  Good work and good luck 8', '2004-01-25 09:31:25.000000', NULL, 1),
(556101, 56041, 3540, '<td valign="top">Funny find on the sign.  I don''t like the lens flares on the left side of the frame though.  This picture looks like its more about the sign than the actual picture though.  Good luck</td>', 'Funny find on the sign.  I don''t like the lens flares on the left side of the frame though.  This picture looks like its more about the sign than the actual picture though.  Good luck', '2004-01-25 09:33:13.000000', NULL, 1),
(556102, 56031, 3540, '<td valign="top">Looks like a grave marker to me.  very strange road sign.  I might''ve tried going greyscale with this one.  Not a lot of color to be lost if you did.</td>', 'Looks like a grave marker to me.  very strange road sign.  I might''ve tried going greyscale with this one.  Not a lot of color to be lost if you did.', '2004-01-25 09:34:48.000000', NULL, 1),
(556104, 55894, 3540, '<td valign="top">Good ironic sign.  You just can''t believe that someone would put up a sign like that unless you actually see it.  Picture is a little bit dark.  Good find on the sign.</td>', 'Good ironic sign.  You just can''t believe that someone would put up a sign like that unless you actually see it.  Picture is a little bit dark.  Good find on the sign.', '2004-01-25 09:36:22.000000', NULL, 1),
