(556909, 55603, 15475, '<td valign="top">Perfect sign for the perfect background!  I love the clearness of the word "SUNSET" on a very bright white sign.</td>', 'Perfect sign for the perfect background!  I love the clearness of the word "SUNSET" on a very bright white sign.', '2004-01-26 00:49:11.000000', NULL, 1),
(556930, 55923, 15475, '<td valign="top">"TOMARE"... instead they should write "SUTOPPU."  High up on the electric pole, a sign buried in millions of cables and wires.  Very Tokyo style!  I think this image captures the whole essence of Japanese culture.</td>', '"TOMARE"... instead they should write "SUTOPPU."  High up on the electric pole, a sign buried in millions of cables and wires.  Very Tokyo style!  I think this image captures the whole essence of Japanese culture.', '2004-01-26 01:00:45.000000', NULL, 1),
(556950, 55894, 15475, '<td valign="top">I am only hoping that the guiding dog would see this sign.  A great picture. Very nice.</td>', 'I am only hoping that the guiding dog would see this sign.  A great picture. Very nice.', '2004-01-26 01:27:41.000000', NULL, 1),
(556954, 56055, 15475, '<td valign="top">Wow!  Yes, the message is clear. Seriously, stop right now or else the wall...  Tight, simple and clear image.  I love it!</td>', 'Wow!  Yes, the message is clear. Seriously, stop right now or else the wall...  Tight, simple and clear image.  I love it!', '2004-01-26 01:34:59.000000', NULL, 1),
