(557545, 55937, 3942, '<td valign="top">A really nice texture, but I don''t like the cropping very much. Nevertheless an interesting and different shot. Good luck for the challenge!</td>', 'A really nice texture, but I don''t like the cropping very much. Nevertheless an interesting and different shot. Good luck for the challenge!', '2004-01-26 10:06:17.000000', NULL, 1),
(557555, 55229, 3942, '<td valign="top">Interesting an different, I like the cropping. Good luck for the challenge!</td>', 'Interesting an different, I like the cropping. Good luck for the challenge!', '2004-01-26 10:12:13.000000', NULL, 1),
(557578, 55447, 3942, '<td valign="top">Not bad, but IMHO there ist some space for improvement too. It could have been more interesting with an off-centered position of the roadsign.  By using another aparture (e.g. F 2.0), the background could have been more unsharp and less distracting. Nevertheless good luck for the challenge!</td>', 'Not bad, but IMHO there ist some space for improvement too. It could have been more interesting with an off-centered position of the roadsign.  By using another aparture (e.g. F 2.0), the background could have been more unsharp and less distracting. Nevertheless good luck for the challenge!', '2004-01-26 10:31:42.000000', NULL, 1),
