INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(558922, 55647, 13136, '<td valign="top">Good sign and background. The shot lacks a bit of focus and contrast. The background is washed out (but it looks like that kind of day, so it was probably unavoidable).</td>', 'Good sign and background. The shot lacks a bit of focus and contrast. The background is washed out (but it looks like that kind of day, so it was probably unavoidable).', '2004-01-27 11:54:04.000000', NULL, 1),
(558925, 56015, 13136, '<td valign="top">Good use of time-lapse to convey motorists disobeying the sign. To me, the trash bags detract from the shot.</td>', 'Good use of time-lapse to convey motorists disobeying the sign. To me, the trash bags detract from the shot.', '2004-01-27 11:57:28.000000', NULL, 1),
(558928, 55971, 13136, '<td valign="top">Sign is overlit. A longer exposure with less light on the sign would bring out a bit more detail around it (like exactly where are the tracks).</td>', 'Sign is overlit. A longer exposure with less light on the sign would bring out a bit more detail around it (like exactly where are the tracks).', '2004-01-27 12:00:45.000000', NULL, 1),
(558930, 55419, 13136, '<td valign="top">I had to come back to it two or three times, but finally, yes. Time-lapse? or light problems?</td>', 'I had to come back to it two or three times, but finally, yes. Time-lapse? or light problems?', '2004-01-27 12:02:20.000000', NULL, 1),
(558989, 55586, 14620, '<td valign="top">Simply beautiful.  One of my favorites.  I like the tones and the clouds are amazing.  Very nice capture!</td>', 'Simply beautiful.  One of my favorites.  I like the tones and the clouds are amazing.  Very nice capture!', '2004-01-27 13:03:13.000000', NULL, 1),
(558990, 55407, 14620, '<td valign="top">Amazing colors!  Some may say oversaturated but I really like it.  It adds to the drama of the photo.  Great way to make a road sign interesting!  Excellent job!</td>', 'Amazing colors!  Some may say oversaturated but I really like it.  It adds to the drama of the photo.  Great way to make a road sign interesting!  Excellent job!', '2004-01-27 13:04:16.000000', NULL, 1),
